<template><div class="table-page meteorology-page"><div class="page-toolbar"><el-tag type="primary">{{ regionName }}</el-tag><el-button type="primary" icon="el-icon-plus" @click="openCreate">新增气象场</el-button><el-button type="success" icon="el-icon-check" @click="enableAll">全部启用</el-button><el-button type="danger" icon="el-icon-delete" :disabled="selected.length===0" @click="removeSelected">批量删除 ({{ selected.length }})</el-button><span class="spacer"/><el-button type="text" icon="el-icon-refresh" @click="refresh">刷新</el-button></div><div class="table-shell"><el-table v-loading="loading" :data="items" border stripe row-key="id" @selection-change="selected=$event"><el-table-column type="selection" width="46"/><el-table-column prop="id" label="ID" width="60"/><el-table-column prop="name" label="名称"/><el-table-column prop="windSpeed" label="风速"/><el-table-column prop="windDirection" label="来风方向"/><el-table-column prop="stabilityClass" label="稳定度"/><el-table-column label="启用"><template slot-scope="s"><el-switch v-model="s.row.isActive" @change="setActive(s.row,$event)"/></template></el-table-column><el-table-column label="操作"><template slot-scope="s"><el-button type="text" @click="openEdit(s.row)">编辑</el-button><el-button type="text" style="color:#f56c6c" @click="remove(s.row)">删除</el-button></template></el-table-column></el-table></div><el-dialog :visible.sync="dialogVisible" :title="dialogMode==='create'?'新增气象场':'编辑气象场'" width="520px"><el-form label-width="110px"><el-form-item label="名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="风速"><el-input-number v-model="form.windSpeed" :min="0.1" :step="0.1"/></el-form-item><el-form-item label="来风方向"><el-input-number v-model="form.windDirection" :min="0" :max="359"/></el-form-item><el-form-item label="稳定度"><el-select v-model="form.stabilityClass"><el-option v-for="c in ['A','B','C','D','E','F']" :key="c" :value="c" :label="c"/></el-select></el-form-item><el-form-item label="是否启用"><el-switch v-model="form.isActive"/></el-form-item></el-form><span slot="footer"><el-button @click="dialogVisible=false">取消</el-button><el-button type="primary" @click="submit">保存</el-button></span></el-dialog></div></template>
<script lang="ts">import Vue from 'vue'; import { meteorologyApi } from '@/api'; import type { Meteorology } from '@/types'; export default Vue.extend({name:'MeteorologyView',data:()=>({items:[] as Meteorology[],loading:false,selected:[] as Meteorology[],dialogVisible:false,dialogMode:'create',editId:null as number|null,form:{name:'',windSpeed:3,windDirection:0,boundaryLayerHeight:800,stabilityClass:'D',temperature:298,humidity:60,cloudCover:2,precipitation:0,isActive:true} as any}),computed:{regionName():string{return this.$store.state.regions.find((r:any)=>r.key===this.$store.state.currentRegionKey)?.name||''}},mounted(){this.refresh()},methods:{async refresh(){this.loading=true;try{this.items=await meteorologyApi.list(0,1000,this.$store.state.currentRegionKey);this.selected=[]}finally{this.loading=false}},openCreate(){this.dialogMode='create';this.editId=null;Object.assign(this.form,{name:'',windSpeed:3,windDirection:0,stabilityClass:'D',isActive:true});this.dialogVisible=true},openEdit(r:Meteorology){this.dialogMode='edit';this.editId=r.id;Object.assign(this.form,r);this.dialogVisible=true},async submit(){if(this.dialogMode==='create')await meteorologyApi.create(this.form,this.$store.state.currentRegionKey);else if(this.editId)await meteorologyApi.update(this.editId,this.form);this.dialogVisible=false;this.refresh()},async setActive(r:Meteorology,isActive:boolean){await meteorologyApi.update(r.id,{isActive});this.refresh()},async enableAll(){await Promise.all(this.items.filter(i=>!i.isActive).map(i=>meteorologyApi.update(i.id,{isActive:true})));this.refresh()},async remove(r:Meteorology){await meteorologyApi.delete(r.id);this.refresh()},async removeSelected(){await Promise.all(this.selected.map(r=>meteorologyApi.delete(r.id)));this.refresh()}}})</script>
